SELECT a.STOCKSNAME AS `股票名称`, a.STOCKCODE AS `股票代码`, ROUND(AVG(a.TVALUE) / 100000000, 2) AS `2026年8月日均成交额(亿)` FROM ANA_STK_EXPR_IDX a JOIN GET_A_SEC_CODE b ON a.INNER_CODE = b.INNER_CODE WHERE a.STOCKSNAME LIKE '%格力电器%' AND a.ENDDATE >= '2026-08-01' AND a.ENDDATE <= '2026-08-31' AND a.TVALUE IS NOT NULL AND b.ISVALID = 1 GROUP BY a.STOCKSNAME, a.STOCKCODE;
200
